const input = $input.item.json;
const customFields = input.wippli_customFormFields || [];

const mappedFields = {};
for (const field of customFields) {
  if (field.name) {
    mappedFields[field.name] = field;
  }
}

input.wippli_customFormFields = mappedFields;

return [{ json: input }];

const merged = {};

for (const block of $input.all().map(i => i.json)) {

  for (const [key, value] of Object.entries(block)) {
    if (typeof value !== 'object' || value === null) {
      merged[key] = value;
    }
  }

  if (block.wippli_customFormFields) {
    merged.wippli_customFormFields = block.wippli_customFormFields;
  }
}

return [{ json: merged }];

// Preserve ALL webhook data and add document URL
const inputData = $input.first().json;
const documentUrl = inputData.wippli_customFormFields?.Drop_document?.value || '';
const question = inputData.wippli_customFormFields?.Map_question?.value || 'Analyze this document';

return [{
  json: {
    ...inputData,
    urlSource: documentUrl,
    wippli_id: inputData.wippliId || inputData.wippli_id || 'unknown',
    question: question,
    user: inputData.user_name || inputData.user || 'system'
  }
}];

const result = $input.first().json;

// Log the entire structure for debugging
console.log('Full Azure result:', JSON.stringify(result, null, 2).substring(0, 500));

// Handle different response structures from Azure Doc Intelligence
const content = result.analyzeResult?.content || 
                result.content || 
                result.analyzeResult?.paragraphs?.map(p => p.content).join('\n\n') || 
                '';

console.log('Extracted content length:', content.length);
console.log('First 100 chars:', content.substring(0, 100));

// Return even if empty to see what we're getting
return [{
  json: {
    text: content,
    pageCount: result.analyzeResult?.pages?.length || 0,
    status: result.status || 'unknown',
    debug_keys: Object.keys(result),
    has_analyzeResult: !!result.analyzeResult
  }
}];

