// Get document content directly from Extract Text node
const docContent = extractedText.text || '';

console.log('Extract Text content length:', docContent.length);
console.log('Original Input wippli_id:', wippliId);
console.log('First 200 chars:', docContent.substring(0, 200));

if (!docContent || docContent.trim().length === 0) {
  throw new Error('No document content from Extract Text node!');
}

return {
  workspace: workspace,
  timestamp: timestamp,
  access_token: loginData.access_token.trim(),
  document_content: docContent,
  question: originalInput.question || 'Analyze this document',
  wippli_id: wippliId,
  user: originalInput.user || 'system',
  pageCount: extractedText.pageCount || 0,
  status: extractedText.status || 'processed'
};

// Pass through necessary data for query nodes
const prepareData = $('Prepare Data').item.json;
const uploadResponse = $('Upload Document').item.json;

console.log('Prepare Data:', JSON.stringify(prepareData, null, 2));
console.log('Upload Response:', JSON.stringify(uploadResponse, null, 2));

// Get token from either 'token' or 'access_token' field
const token = prepareData.token || prepareData.access_token;

if (!token) {
  throw new Error('No token found in Prepare Data!');
}

return {
  workspace: prepareData.workspace,
  token: token,
  wippli_id: prepareData.wippli_id,
  question: prepareData.question,
  user: prepareData.user,
  track_id: uploadResponse.track_id || 'N/A'
};

// Get graph data from Extract Graph
