    label: e.entity_name,
    type: e.entity_type,
    description: (e.description || 'No description').replace(/"/g, '&quot;').replace(/\n/g, ' '),
    color: typeColors[e.entity_type] || typeColors.UNKNOWN
  }));

  // Transform relationships
  const links = relationships.map(r => ({
    source: r.src_id,
    target: r.tgt_id,
    label: (r.keywords || '').split(',')[0].replace(/"/g, '&quot;')
  }));

  const nodesJson = JSON.stringify(nodes);
