const flatteningData = $('Flattening Code').first().json;
const wippliId = flatteningData.wippli_id;
const supplierId = flatteningData.supplier_id;

const nodes = $input.all().map(({ json }) => {
  const base = { ...json };
  const items = [];

  Object.keys(json).forEach(key => {
    const match = key.match(/^item(\d+)_(.+)/);
    if (match) {
      const index = parseInt(match[1], 10) - 1;
      const field = match[2];
      if (!items[index]) items[index] = {};
      items[index][field] = json[key];
      delete base[key];
    }
  });

  if (items.length > 0) {
    base.items = items.filter(Boolean);
  }

  return base;
});

return [{ json: { wippliId, supplierId, nodes } }];

